<?php/** * Service 4: Transparency Labels — V1.0.8.4 */namespace MegaGovern;if ( ! defined( 'ABSPATH' ) ) { exit; }class Labels {    private const EU_ICON_MAP = array(        'human'        => 'basic',        'ai_assisted'  => 'partially-ai',        'ai_generated' => 'fully-ai',        'deepfake'     => 'fully-ai'    );    private const EU_ICON_COLORS = array( 'black', 'white' );    private static $done_title   = array();    private static $done_content = array();    private static $url_cache    = array();        public function __construct() {        add_filter( 'the_title', array( $this, 'add_badge_to_title' ), 10, 2 );        add_filter( 'the_content', array( $this, 'prepend_meta_to_content' ), 8 );        add_filter( 'the_content', array( $this, 'add_policy_link' ), 30 );        add_filter( 'the_content', array( $this, 'add_image_overlay' ), 35 );        add_action( 'wp_footer', array( $this, 'js_fallback' ), 99 );        add_action( 'woocommerce_single_product_summary', array( $this, 'render_woo' ), 5 );        add_action( 'wp_head', array( $this, 'inline_styles' ), 9999 );        add_action( 'wp_enqueue_scripts', array( $this, 'enqueue' ) );        add_shortcode( 'megagovern_label', array( $this, 'shortcode' ) );        add_filter( 'wp_get_attachment_image_attributes', array( $this, 'filter_image_attrs' ), 10, 3 );        add_filter( 'wp_nav_menu_args', array( $this, 'disable_title_filter_for_menu' ) );        add_filter( 'wp_nav_menu', array( $this, 'enable_title_filter_after_menu' ) );    }        private function is_post_type_enabled( int $post_id = 0 ): bool {        if ( ! $post_id ) {            $post_id = (int) ( get_the_ID() ?: get_queried_object_id() );        }        if ( ! $post_id ) return false;        $post_type = get_post_type( $post_id );        if ( ! $post_type || in_array( $post_type, array( 'nav_menu_item', 'revision', 'custom_css', 'customize_changeset' ), true ) ) {            return false;        }        $allowed = get_option( 'megagovern_post_types' );        if ( false === $allowed || null === $allowed ) {            $allowed = get_option( 'megagovern_enabled_post_types' );        }        if ( false === $allowed || null === $allowed ) {            $allowed = get_option( 'megagovern_cpt_settings' );        }        if ( false === $allowed || null === $allowed ) {            $allowed = array( 'post' );        }        $allowed_array = (array) $allowed;        return in_array( $post_type, $allowed_array, true );    }        public function disable_title_filter_for_menu( array $args ): array {        remove_filter( 'the_title', array( $this, 'add_badge_to_title' ), 10 );        return $args;    }        public function enable_title_filter_after_menu( string $nav_menu ): string {        add_filter( 'the_title', array( $this, 'add_badge_to_title' ), 10, 2 );        return $nav_menu;    }        public function enqueue(): void {        if ( file_exists( MEGAGOVERN_PATH . 'assets/css/public.css' ) ) {            wp_enqueue_style( 'megagovern-public', MEGAGOVERN_URL . 'assets/css/public.css', array(), MEGAGOVERN_VERSION );        }    }        public function inline_styles(): void {        echo '<style id="mga-eu-label-inline">            .mga-meta-row{display:flex;align-items:center;gap:8px;margin:8px 0 16px;font-size:13px;color:#646970;flex-wrap:wrap}            .mga-eu-label{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:600;padding:4px 8px;border-radius:4px;background:#f0f6fc;border:1px solid #c5d9ed;color:#0a4a70;line-height:1.2}            .mga-eu-label img{width:18px;height:18px}            .mga-eu-label--title{margin-left:8px;font-size:11px;padding:2px 6px;vertical-align:middle}            .mga-meta-author{font-weight:500;color:#1d2327;text-decoration:none}            .mga-meta-sep{color:#c3c4c7}            .mga-policy-link{display:block;margin:24px 0 8px;padding:10px 14px;font-size:12px;color:#50575e;background:#f0f0f1;border-radius:6px;border:1px solid #dcdcde;text-decoration:none}            .mga-image-wrapper{position:relative;display:block;max-width:100%;line-height:0}            .mga-image-label{position:absolute;z-index:10;bottom:14px;right:14px;width:auto!important;height:auto!important}            .mga-image-label img{width:130px!important}            .mga-image-label--bottom-left{left:14px;right:auto}            .mga-image-label--top-right{top:14px;bottom:auto;right:14px}            .mga-image-label--top-left{top:14px;left:14px;right:auto;bottom:auto}            @media(max-width:600px){            .mga-image-label img{width:62px!important;height:62px!important}            .mga-image-label{bottom:8px;right:8px}            }        </style>';    }        public static function get_eu_icon_url( string $type, string $color = 'black', string $op = '100' ): string {        $folder = isset( self::EU_ICON_MAP[ $type ] ) ? self::EU_ICON_MAP[ $type ] : 'basic';        $color  = in_array( $color, self::EU_ICON_COLORS, true ) ? $color : 'black';        $file   = $folder . '-' . $color . ( '50' === $op ? '-50' : '' ) . '.svg';        $path   = MEGAGOVERN_PATH . 'assets/images/eu-icons/' . $folder . '/' . $file;        $url    = MEGAGOVERN_URL . 'assets/images/eu-icons/' . $folder . '/' . $file;        if ( file_exists( $path ) ) return $url;        $fb     = MEGAGOVERN_PATH . 'assets/images/eu-icons/basic/basic-' . $color . ( '50' === $op ? '-50' : '' ) . '.svg';        $fb_url = MEGAGOVERN_URL . 'assets/images/eu-icons/basic/basic-' . $color . ( '50' === $op ? '-50' : '' ) . '.svg';        return file_exists( $fb ) ? $fb_url : $url;    }        public static function get_image_icon_url( string $type ): string {        $style = (string) get_option( 'megagovern_image_label_style', 'white-50' );        $c     = false !== strpos( $style, 'white' ) ? 'white' : 'black';        $o     = false !== strpos( $style, '50' ) ? '50' : '100';        return self::get_eu_icon_url( $type, $c, $o );    }        public static function render( string $type, array $args = array() ): string {        if ( ! isset( self::EU_ICON_MAP[ $type ] ) ) return '';        $custom = get_option( 'megagovern_custom_label_text', array() );        $is_pro = self::can_customize();        $tpl    = MEGAGOVERN_PATH . 'templates/public/label.php';        if ( file_exists( $tpl ) ) {            ob_start();            include $tpl;            $h = trim( (string) ob_get_clean() );            if ( $h !== '' ) return $h;        }        $labels = array(            'human'        => 'Human Created',            'ai_assisted'  => 'AI-Assisted',            'ai_generated' => 'AI-Generated',            'deepfake'     => 'Synthetic Media'        );        $text = isset( $labels[ $type ] ) ? $labels[ $type ] : $type;        if ( $is_pro && ! empty( $custom[ $type ] ) ) {            $text = $custom[ $type ];        }        $icon = self::get_eu_icon_url( $type, 'black', '100' );        return '<span class="mga-eu-label"><img src="' . esc_url( $icon ) . '" alt="">' . esc_html( $text ) . '</span>';    }        public static function render_for_post( int $id ): string {        $d = get_post_meta( $id, '_megagovern_declaration', true );        if ( empty( $d ) || ! isset( self::EU_ICON_MAP[ $d ] ) ) return '';        return self::render( $d );    }        public static function can_customize(): bool {        return class_exists( '\MegaGovern\License' ) && ( License::is_pro() || License::is_agency() );    }        public function shortcode( array $atts ): string {        $atts = shortcode_atts( array( 'type' => '' ), $atts );        $type = isset( $atts['type'] ) ? sanitize_text_field( wp_unslash( $atts['type'] ) ) : '';        if ( empty( $type ) ) {            $type = get_post_meta( get_the_ID() ?: get_queried_object_id(), '_megagovern_declaration', true );        }        if ( empty( $type ) || ! isset( self::EU_ICON_MAP[ $type ] ) ) return '';        return self::render( $type );    }        public function render_woo(): void {        if ( is_admin() || ! is_singular( 'product' ) ) return;        if ( ! (bool) get_option( 'megagovern_content_label_enabled', true ) ) return;        $id = (int) ( get_the_ID() ?: get_queried_object_id() );        if ( ! $this->is_post_type_enabled( $id ) ) return;        echo wp_kses_post( self::render_for_post( $id ) );    }        public function add_badge_to_title( string $title, int $post_id = 0 ): string {        if ( is_admin() ) return $title;        if ( ! (bool) get_option( 'megagovern_content_label_enabled', true ) ) return $title;        if ( ! $post_id ) {            $post_id = (int) ( get_the_ID() ?: get_queried_object_id() );        }        if ( ! in_the_loop() && ! is_singular() ) return $title;        if ( $post_id && $post_id !== (int) get_queried_object_id() ) return $title;        if ( ! $this->is_post_type_enabled( $post_id ) ) return $title;        if ( isset( self::$done_title[ $post_id ] ) ) return $title;        $pos = get_option( 'megagovern_label_position', 'top' );        if ( 'manual' === $pos ) return $title;        $decl = get_post_meta( $post_id, '_megagovern_declaration', true );        if ( empty( $decl ) || ! isset( self::EU_ICON_MAP[ $decl ] ) ) return $title;        self::$done_title[ $post_id ] = true;        $badge = self::render( $decl );        $badge = str_replace( 'mga-eu-label"', 'mga-eu-label mga-eu-label--title"', $badge );        return $title . ' ' . $badge;    }        public function prepend_meta_to_content( string $content ): string {        if ( is_admin() || ! is_singular() ) return $content;        if ( ! (bool) get_option( 'megagovern_content_label_enabled', true ) ) return $content;        $post_id = (int) ( get_the_ID() ?: get_queried_object_id() );        if ( ! $post_id || $post_id !== (int) get_queried_object_id() ) return $content;        if ( ! $this->is_post_type_enabled( $post_id ) ) return $content;        if ( isset( self::$done_content[ $post_id ] ) ) return $content;        $pos = get_option( 'megagovern_label_position', 'top' );        if ( 'manual' === $pos ) return $content;        $decl = get_post_meta( $post_id, '_megagovern_declaration', true );        if ( empty( $decl ) || ! isset( self::EU_ICON_MAP[ $decl ] ) ) return $content;        self::$done_content[ $post_id ] = true;        $label  = self::render( $decl );        $aid    = (int) get_post_field( 'post_author', $post_id );        $author = $aid ? get_the_author_meta( 'display_name', $aid ) : '';        $aurl   = $aid ? get_author_posts_url( $aid ) : '#';        $date   = get_the_date( '', $post_id );        $meta = '<div class="mga-meta-row">' . $label;        if ( $author ) {            $meta .= '<a href="' . esc_url( $aurl ) . '" class="mga-meta-author">' . esc_html( $author ) . '</a><span class="mga-meta-sep">·</span>';        }        $meta .= '<span>' . esc_html( $date ) . '</span></div>';        return $meta . $content;    }        public function add_policy_link( string $content ): string {        if ( is_admin() || ! is_singular() ) return $content;        if ( ! (bool) get_option( 'megagovern_content_label_enabled', true ) ) return $content;        if ( 'both' !== get_option( 'megagovern_label_position', 'top' ) ) return $content;        $pid = (int) ( get_the_ID() ?: get_queried_object_id() );        if ( ! $this->is_post_type_enabled( $pid ) ) return $content;        $decl = get_post_meta( $pid, '_megagovern_declaration', true );        if ( empty( $decl ) || ! isset( self::EU_ICON_MAP[ $decl ] ) ) return $content;        $url  = home_url( '/ai-policy/' );        $info = class_exists( '\MegaGovern\Helpers' ) ? \MegaGovern\Helpers::declaration_type( $decl ) : array();        $txt  = isset( $info['label'] ) ? $info['label'] : $decl;        /* translators: %s: declaration type label (e.g., Human Made, AI Generated) */        return $content . '<a href="' . esc_url( $url ) . '" class="mga-policy-link">🔍 ' . esc_html( sprintf( __( 'AI Transparency: %s. View full AI policy →', 'megagovern' ), $txt ) ) . '</a>';    }        public function add_image_overlay( string $content ): string {        if ( is_admin() || ! is_singular() ) return $content;        if ( ! get_option( 'megagovern_image_label_enabled', true ) ) return $content;        $pid = (int) ( get_the_ID() ?: get_queried_object_id() );        if ( ! $this->is_post_type_enabled( $pid ) ) return $content;        $pos     = get_option( 'megagovern_image_label_position', 'bottom-right' );        $content = preg_replace_callback( '/<img[^>]+>/i', function( $m ) use ( $pos ) {            $img = $m[0];            if ( false !== strpos( $img, 'mga-image-wrapper' ) || false !== strpos( $img, 'mga-image-label' ) ) return $img;            $id = 0;            if ( preg_match( '/wp-image-(\d+)/i', $img, $x ) ) {                $id = (int) $x[1];            } elseif ( preg_match( '/data-id=["\'](\d+)["\']/i', $img, $x ) ) {                $id = (int) $x[1];            } else {                if ( preg_match( '/src=["\']([^"\']+)["\']/i', $img, $s ) ) {                    $src   = $s[1];                    $clean = preg_replace( '/-\d+x\d+(?=\.(jpg|jpeg|png|webp|gif)$)/i', '', $src );                    if ( isset( self::$url_cache[ $clean ] ) ) {                        $id = self::$url_cache[ $clean ];                    } else {                        $id = attachment_url_to_postid( $clean ) ?: attachment_url_to_postid( $src );                        self::$url_cache[ $clean ] = $id;                    }                }            }            if ( ! $id ) return $img;            $decl = get_post_meta( $id, '_megagovern_declaration', true );            if ( empty( $decl ) || 'human' === $decl ) return $img;            $icon = self::get_image_icon_url( $decl );            $over = '<span class="mga-image-label mga-image-label--' . esc_attr( $pos ) . '"><img src="' . esc_url( $icon ) . '" alt="" loading="lazy" width="36" height="36"></span>';            return '<span class="mga-image-wrapper">' . $img . $over . '</span>';        }, $content );        return $content;    }        public function js_fallback(): void {        if ( is_admin() || ! is_singular() ) return;        $pid = (int) get_queried_object_id();        if ( ! $this->is_post_type_enabled( $pid ) ) return;        if ( ! empty( self::$done_content[ $pid ] ) ) return;        $decl = get_post_meta( $pid, '_megagovern_declaration', true );        if ( empty( $decl ) || ! isset( self::EU_ICON_MAP[ $decl ] ) ) return;        if ( ! (bool) get_option( 'megagovern_content_label_enabled', true ) ) return;        $label  = self::render( $decl );        $aid    = (int) get_post_field( 'post_author', $pid );        $author = $aid ? get_the_author_meta( 'display_name', $aid ) : '';        $date   = get_the_date( '', $pid );        $meta = '<div class="mga-meta-row">' . $label;        if ( $author ) $meta .= esc_html( $author ) . ' · ';        $meta .= esc_html( $date ) . '</div>';        $selectors = '.entry-content, .elementor-widget-container, .et-l--post, .et_builder_inner_content, .brxe-post-content, .woocommerce-product-details__short-description, .single-product-summary';        echo '<script id="mga-universal-fallback">(function(){var meta=' . wp_json_encode( $meta ) . ';var c=document.querySelector(' . wp_json_encode( $selectors ) . ');if(c&&!document.querySelector(".mga-meta-row")){c.insertAdjacentHTML("afterbegin",meta);}})();</script>';    }        public function filter_image_attrs( $attr, $attachment, $image ): array {        if ( ! is_array( $attr ) ) {            return $attr;        }        if ( ! $attachment instanceof \WP_Post ) {            return $attr;        }        if ( ! get_option( 'megagovern_image_label_enabled', true ) ) {            return $attr;        }        $decl = get_post_meta( $attachment->ID, '_megagovern_declaration', true );        if ( ! empty( $decl ) && 'human' !== $decl ) {            $attr['data-mga-declaration'] = esc_attr( $decl );            $attr['data-mga-icon']        = esc_url( self::get_image_icon_url( $decl ) );            $attr['data-mga-position']    = esc_attr( get_option( 'megagovern_image_label_position', 'bottom-right' ) );        }        return $attr;    }}